#!/usr/bin/env python3
"""Prepare blinded local listening trials; never fabricate participant responses."""
import pathlib,json,wave,random,numpy as np,hashlib
root=pathlib.Path(__file__).resolve().parents[1];out=root/'build/english6';target=out/'listening';target.mkdir(exist_ok=True);corpus=json.loads((out/'corpus.json').read_text());cases=[];answers={};r=random.Random(640611)
items=[(c,e,s) for c in corpus for e in ['baseline','prototype'] for s in c['segments']];r.shuffle(items)
for i,(item,engine,segment) in enumerate(items):
 with wave.open(str(out/f"{item['id']}-{engine}.wav")) as w:data=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').reshape(-1,2).mean(axis=1)/32768
 start=round(segment['start']*44100*60/120/96);end=round(segment['end']*44100*60/120/96);clip=data[start:end].copy();gain=min(.08/max(float(np.sqrt(np.mean(clip*clip))),1e-9),.7/max(float(max(abs(clip))),1e-9));clip*=gain
 n=min(100,len(clip)//4);clip[:n]*=np.linspace(0,1,n);clip[-n:]*=np.linspace(1,0,n)
 case=f's{i:02d}';path=target/(case+'.wav')
 with wave.open(str(path),'wb') as w:w.setnchannels(1);w.setsampwidth(2);w.setframerate(44100);w.writeframes(np.rint(clip*32767).astype('<i2').tobytes())
 choices=['heed','hid','head','had'] if item['group']=='vowels' else ['see','she','pea','bee'];cases.append({'id':case,'audio':case+'.wav','note':item['note'],'group':item['group'],'choices':choices});answers[case]={'engine':engine,'note':item['note'],'group':item['group'],'word':segment['word'],'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'listening_gain':gain}
(target/'answers.json').write_text(json.dumps({'note':'Do not view before completing the blinded test. Audio level matched for listening only; not DSP/headroom data.','answers':answers},indent=2)+'\n')
html='''<!doctype html><meta charset="utf-8"><title>KIRA-9 blinded phoneme test</title><style>body{font:18px system-ui;background:#10151e;color:#eee;max-width:760px;margin:40px auto;padding:20px}button,select{font:inherit;padding:12px;margin:6px;background:#28364d;color:white;border:1px solid #6485a0;border-radius:6px}small{color:#c4cfdb}#choice button{min-width:100px}</style><h1>Blinded English phoneme test</h1><p>Use headphones. Identify the word you hear. Engine identity and target answers are hidden. Do not open answers.json before judging. These are research stimuli, not a released voice.</p><label>Register <select id="register"><option>60</option><option>48</option><option>72</option></select></label><button id="start">Start register</button><p id="status"></p><audio id="audio" controls></audio><div id="choice"></div><button id="export">Export responses</button><p><small>16 trials per register. You can replay each clip. “Unclear” counts as an unsuccessful identification. No results are sent anywhere. Export before starting another register.</small></p><script>
const cases=CASES;let trials=[],position=0,responses=[];const $=x=>document.getElementById(x);
function show(){if(position>=trials.length){$('status').textContent='Block complete. Export responses.';$('choice').replaceChildren();return;}const c=trials[position];$('status').textContent=`Trial ${position+1} of ${trials.length}`;$('audio').src=c.audio;$('choice').replaceChildren();for(const label of [...c.choices,'Unclear']){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{responses.push({id:c.id,response:label});position++;show()};$('choice').append(b)}}
$('start').onclick=()=>{trials=cases.filter(c=>c.note===Number($('register').value));position=0;responses=[];show()};$('export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({protocol:'english6-blind-v1',register:Number($('register').value),responses},null,2)],{type:'application/json'}));a.download='KIRA9-listening-responses.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('start').click();</script>'''.replace('CASES',json.dumps(cases))
(target/'index.html').write_text(html);(out/'listening-status.json').write_text(json.dumps({'prepared_trials':len(cases),'default_trials_per_register':16,'human_participants':0,'human_results':'NOT PERFORMED','blinding':'Targets and engine only in separate answer key; random audio IDs; fixed balanced register blocks.','normalization':'Listening only: RMS .08 with .7 peak bound; no firmware/headroom modification.'},indent=2)+'\n');print('Prepared 48 blinded stimuli, 16 per register. Human results NOT PERFORMED.')
